// @generated by:gauntlet run:godseye-local-coding-runners
import { randomUUID } from "node:crypto";
import { InfrastructureEngine } from "@godseye/core";
import { schema } from "@godseye/store";
import { eq } from "drizzle-orm";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { controlled } from "./helpers/agents-fixture.js";
import { type CodingFixture, codingFixture, codingResult } from "./helpers/coding-fixture.js";

describe("coding tasks use real Foundation admission and evidence", () => {
  let f: CodingFixture;
  beforeEach(async () => {
    f = await codingFixture();
  });
  afterEach(async () => {
    await f.store.close();
  });

  it("T-AC-781 keeps preparation and retained results owner-only", async () => {
    const actor = { id: "coding-service", kind: "service" as const, projectIds: [f.project.id] };
    await expect(
      f.infrastructure.coding.prepare(actor, f.input, randomUUID()),
    ).rejects.toMatchObject({ code: "FORBIDDEN" });
    await expect(f.infrastructure.coding.overview(actor)).rejects.toMatchObject({
      code: "FORBIDDEN",
    });
    expect((await f.infrastructure.coding.overview(f.freshOwner())).preparations).toHaveLength(0);
  });
  it("T-AC-783 replays the immutable preparation and rejects a changed duplicate", async () => {
    const key = randomUUID();
    const first = await f.prepare({}, key);
    expect(await f.prepare({}, key)).toEqual(first);
    await expect(f.prepare({ input: "Different intent" }, key)).rejects.toMatchObject({
      code: "IDEMPOTENCY_CONFLICT",
    });
    expect((await f.infrastructure.coding.overview(f.freshOwner())).preparations).toHaveLength(1);
  });
  it("T-AC-787 unavailable execution preserves preparation without task or reservation", async () => {
    const p = await f.prepare();
    f.provider.qualified = false;
    await expect(f.admit(p)).rejects.toMatchObject({ code: "CAPABILITY_UNAVAILABLE" });
    expect((await f.infrastructure.coding.overview(f.freshOwner())).tasks).toHaveLength(0);
    expect(
      (await f.infrastructure.foundation.getBudget(f.freshOwner(), f.project.id)).reservedMicros,
    ).toBe(0);
    expect(f.provider.submissions).toHaveLength(0);
  });
  it("T-AC-787 reports unavailable capacity even when the provider advertises availability", async () => {
    const unconfigured = new InfrastructureEngine(f.store, {
      ...f.configuration,
      coding: { provider: f.provider },
    });
    const overview = await unconfigured.coding.overview(f.freshOwner());
    expect(overview.capabilities).toHaveLength(2);
    expect(overview.capabilities.every((capability) => !capability.available)).toBe(true);
    expect(f.provider.submissions).toHaveLength(0);
  });
  it("T-AC-782 rejects independently observed source identity mismatch", async () => {
    const p = await f.prepare();
    f.provider.sourceChange = { repositoryHash: p.repositoryHash, commitSha: "b".repeat(40) };
    await expect(f.admit(p)).rejects.toMatchObject({ code: "SOURCE_MISMATCH" });
    expect((await f.infrastructure.coding.overview(f.freshOwner())).tasks).toHaveLength(0);
  });
  it("T-AC-782 rejects a repository binding changed after preparation", async () => {
    const p = await f.prepare();
    await f.core.configureRepository(
      f.freshOwner(),
      f.project.id,
      { ...p.repository, branch: "other" },
      f.project.revision,
      randomUUID(),
    );
    await expect(f.admit(p)).rejects.toMatchObject({ code: "REVISION_CONFLICT" });
    expect(f.provider.submissions).toHaveLength(0);
  });
  it("T-AC-782 held environments cannot admit coding work", async () => {
    const p = await f.prepare();
    await f.store.db
      .update(schema.environments)
      .set({ recoveryHold: true })
      .where(eq(schema.environments.id, f.development.id));
    await expect(f.admit(p)).rejects.toMatchObject({ code: "RECOVERY_HOLD" });
    expect(
      (await f.infrastructure.foundation.getBudget(f.freshOwner(), f.project.id)).reservedMicros,
    ).toBe(0);
  });
  it.each([
    { network: "none" as const },
    { commitSha: "b".repeat(40) },
    { resources: { memoryMiB: 512, cpuMilliCores: 500, maxProcesses: 32, diskMiB: 64 } },
    { expiresAt: "2026-11-11T11:59:59.000Z" },
  ])(
    "T-AC-787 rejects stale, foreign or oversized qualification without reserving %j",
    async (change) => {
      const p = await f.prepare();
      f.provider.qualificationChange = change;
      const admitted = await f.admit(p).then(
        () => true,
        () => false,
      );
      expect(admitted).toBe(false);
      expect((await f.infrastructure.coding.overview(f.freshOwner())).tasks).toHaveLength(0);
      expect(
        (await f.infrastructure.foundation.getBudget(f.freshOwner(), f.project.id)).reservedMicros,
      ).toBe(0);
    },
  );
  it("T-AC-783 duplicate admission retains one task and one reservation", async () => {
    const p = await f.prepare();
    const key = randomUUID();
    const first = await f.admit(p, key);
    expect(await f.admit(p, key)).toEqual(first);
    expect((await f.infrastructure.coding.overview(f.freshOwner())).tasks).toHaveLength(1);
    expect(
      (await f.infrastructure.foundation.getBudget(f.freshOwner(), f.project.id)).reservedMicros,
    ).toBe(f.input.limits.maxCostMicros);
  });
  it("T-AC-790 publishes an exact bounded patch only after closed execution", async () => {
    const task = await f.admit(await f.prepare());
    await f.work();
    const detail = await f.detail(task.id);
    expect(detail.task).toMatchObject({
      state: "succeeded",
      cleanupState: "stopped",
      submissionIntended: true,
    });
    expect(detail.result).toMatchObject({
      taskId: task.id,
      worktreeId: task.worktree.id,
      usage: { accounting: "unknown", costMicros: null },
    });
    expect(f.provider.submissions).toHaveLength(1);
    expect(
      (await f.infrastructure.foundation.getBudget(f.freshOwner(), f.project.id)).reservedMicros,
    ).toBe(0);
  });
  it("T-AC-790 refuses a valid-looking patch whose bytes do not match its digest", async () => {
    f.provider.submitScript = async (request) => {
      const result = codingResult(request);
      if (!result.patch) throw new Error("Fixture patch missing");
      result.patch.sha256 = "0".repeat(64);
      return { ...f.provider.success(request), result };
    };
    const task = await f.admit(await f.prepare());
    await f.work();
    expect((await f.detail(task.id)).result).toBeNull();
    expect((await f.detail(task.id)).task.state).not.toBe("succeeded");
  });
  it("T-AC-790 rolls back publication when the deadline passes after the final result write await", async () => {
    const task = await f.admit(await f.prepare());
    const transaction = f.store.transaction.bind(f.store);
    let expiredAtPublication = false;
    // Preserve real PGlite statements and rollback; only advance the clock after
    // the result mutation has actually completed, before transaction commit.
    f.store.transaction = (work) =>
      transaction((tx) =>
        work(
          new Proxy(tx, {
            get(target, property, receiver) {
              if (property !== "update") return Reflect.get(target, property, receiver);
              return (table: Parameters<typeof tx.update>[0]) =>
                new Proxy(tx.update(table), {
                  get(update, field, updateReceiver) {
                    if (field !== "set") return Reflect.get(update, field, updateReceiver);
                    return (values: Record<string, unknown>) => {
                      const query = Reflect.apply(Reflect.get(update, "set"), update, [
                        values,
                      ]) as object;
                      if (table !== schema.codingTasks || !values.result) return query;
                      return new Proxy(query, {
                        get(selected, key, selectedReceiver) {
                          if (key !== "where") return Reflect.get(selected, key, selectedReceiver);
                          return (...args: unknown[]) => {
                            const operation = Reflect.apply(
                              Reflect.get(selected, "where"),
                              selected,
                              args,
                            ) as PromiseLike<unknown>;
                            return Promise.resolve(operation).then((result) => {
                              expiredAtPublication = true;
                              f.clock.advance(30001);
                              return result;
                            });
                          };
                        },
                      });
                    };
                  },
                });
            },
          }),
        ),
      );
    try {
      await f.work();
      expect(expiredAtPublication).toBe(true);
      expect((await f.detail(task.id)).result).toBeNull();
      expect((await f.detail(task.id)).task.state).not.toBe("succeeded");
    } finally {
      f.store.transaction = transaction;
    }
  });
  it("T-AC-792 retains the patch and observed failed checks for owner review", async () => {
    f.provider.submitScript = async (request) => {
      const result = codingResult(request);
      result.tests = [{ profile: "test", status: "failed", exitCode: 1, log: null }];
      return { ...f.provider.success(request), state: "failed", result };
    };
    const task = await f.admit(await f.prepare({ testProfile: "test" }));
    await f.work();
    const detail = await f.detail(task.id);
    expect(detail.task.state).toBe("failed");
    expect(detail.result?.patch?.content).toContain("+after");
    expect(detail.result?.tests).toMatchObject([{ status: "failed", exitCode: 1 }]);
  });
  it("T-AC-792 does not accept a runner summary as passing requested tests", async () => {
    const task = await f.admit(await f.prepare({ testProfile: "test" }));
    await f.work();
    const detail = await f.detail(task.id);
    expect(detail.result?.tests).toMatchObject([{ profile: "test", status: "not-run" }]);
    expect(detail.task.state).not.toBe("succeeded");
  });
  it("T-AC-788 reconciles unknown execution read-only with the original correlation", async () => {
    f.provider.submitScript = async () => ({
      state: "unknown",
      stopped: false,
      grantsRevoked: false,
      workspace: "quarantined",
    });
    const task = await f.admit(await f.prepare());
    await f.work();
    expect((await f.detail(task.id)).task).toMatchObject({
      state: "unknown",
      cleanupState: "quarantined",
    });
    expect(
      (await f.infrastructure.foundation.getBudget(f.freshOwner(), f.project.id)).reservedMicros,
    ).toBe(f.input.limits.maxCostMicros);
    const reopened = f.build();
    await reopened.coding.reconcile(f.freshOwner(), task.id, randomUUID());
    expect(f.provider.submissions).toHaveLength(1);
    expect(f.provider.inspections).toHaveLength(1);
    expect(f.provider.inspections[0]).toMatchObject({
      taskId: task.id,
      correlationId: task.correlationId,
      worktreeId: task.worktree.id,
    });
    expect((await reopened.coding.detail(f.freshOwner(), task.id)).task.state).toBe("succeeded");
  });
  it.each(["hold", "expiry"] as const)(
    "T-AC-789 reconciles physical stop after %s without publishing old output",
    async (cause) => {
      f.provider.submitScript = async () => ({
        state: "unknown",
        stopped: false,
        grantsRevoked: false,
        workspace: "quarantined",
      });
      const task = await f.admit(await f.prepare());
      await f.work();
      if (cause === "hold")
        await f.store.db
          .update(schema.environments)
          .set({ recoveryHold: true })
          .where(eq(schema.environments.id, f.development.id));
      else f.clock.advance(30001);
      await f.infrastructure.coding.reconcile(f.freshOwner(), task.id, randomUUID());
      const detail = await f.detail(task.id);
      expect(f.provider.submissions).toHaveLength(1);
      expect(f.provider.inspections).toHaveLength(1);
      expect(detail.task).toMatchObject({ state: "cancelled", cleanupState: "stopped" });
      expect(detail.result).toBeNull();
      expect(
        (await f.infrastructure.foundation.getBudget(f.freshOwner(), f.project.id)).reservedMicros,
      ).toBe(0);
    },
  );
  it("T-AC-789 generic Foundation cancellation of unknown work prevents late result publication", async () => {
    f.provider.submitScript = async () => ({
      state: "unknown",
      stopped: false,
      grantsRevoked: false,
      workspace: "quarantined",
    });
    const task = await f.admit(await f.prepare());
    await f.work();
    if (!task.runId) throw new Error("Missing coding Foundation run");
    await f.infrastructure.foundation.cancel(f.freshOwner(), task.runId, randomUUID());
    await f.infrastructure.coding.reconcile(f.freshOwner(), task.id, randomUUID());
    const detail = await f.detail(task.id);
    expect(f.provider.submissions).toHaveLength(1);
    expect(f.provider.inspections).toHaveLength(1);
    expect(detail.task).toMatchObject({ state: "cancelled", cleanupState: "stopped" });
    expect(detail.result).toBeNull();
  });
  it("T-AC-789 queued cancellation prevents physical submission", async () => {
    const task = await f.admit(await f.prepare());
    await f.infrastructure.coding.cancel(f.freshOwner(), task.id, randomUUID());
    await f.work();
    expect(f.provider.submissions).toHaveLength(0);
    expect((await f.detail(task.id)).task.state).toBe("cancelled");
  });
  it("T-AC-789 revocation during preparation prevents physical submission", async () => {
    const task = await f.admit(await f.prepare());
    const entered = controlled<void>();
    const release = controlled<void>();
    f.provider.beforeSubmit = async () => {
      entered.resolve();
      await release.promise;
    };
    const tick = f.work();
    await entered.promise;
    await f.infrastructure.coding.cancel(f.freshOwner(), task.id, randomUUID());
    release.resolve();
    await tick;
    expect(f.provider.submissions).toHaveLength(0);
    expect((await f.detail(task.id)).result).toBeNull();
  });
  it("T-AC-789 missing physical stop proof cannot report success or release its reservation", async () => {
    f.provider.submitScript = async (request) => ({
      ...f.provider.success(request),
      stopped: false,
    });
    const task = await f.admit(await f.prepare());
    await f.work();
    const detail = await f.detail(task.id);
    expect(detail.task).toMatchObject({ state: "unknown", cleanupState: "quarantined" });
    expect(detail.result).toBeNull();
    expect(
      (await f.infrastructure.foundation.getBudget(f.freshOwner(), f.project.id)).reservedMicros,
    ).toBe(f.input.limits.maxCostMicros);
  });
});
